// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { typedndarray } from '@stdlib/types/ndarray';

/**
* Computes the Cartesian product for two one-dimensional ndarrays.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a one-dimensional input ndarray.
*     -   a two-dimensional output ndarray.
*
* @param arrays - array-like object containing ndarrays
* @returns output ndarray
*
* @example
* var vector = require( '@stdlib/ndarray/vector/ctor' );
* var zeros = require( '@stdlib/ndarray/zeros' );
*
* var x = vector( [ 1.0, 2.0 ], 'generic' );
* var y = vector( [ 3.0, 4.0 ], 'generic' );
* var out = zeros( [ 4, 2 ], {
*     'dtype': 'generic'
* });
*
* var v = gcartesianProduct( [ x, y, out ] );
* // returns <ndarray>[ [ 1.0, 3.0 ], [ 1.0, 4.0 ], [ 2.0, 3.0 ], [ 2.0, 4.0 ] ]
*
* var bool = ( v === out );
* // returns true
*/
declare function gcartesianProduct<T extends typedndarray<unknown> = typedndarray<unknown>>( arrays: [ T, T, T ] ): T;


// EXPORTS //

export = gcartesianProduct;
